import Link from "next/link";
import type { Metadata } from "next";
import { IssueCard } from "@/components/domain/issue/issue-card";
import { ProjectCard } from "@/components/domain/project/project-card";
import { UsagePanel } from "@/components/domain/billing/usage-panel";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { getBillingSummary } from "@/server/services/billing-service";
import { listIssues } from "@/server/services/issue-service";
import { listProjects } from "@/server/services/project-service";
import type { BillingSummary } from "@/types/billing";
import { loadTenantContext } from "./_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Overview",
};

const RECENT_ISSUE_LIMIT = 8;
const PROJECT_LIMIT = 6;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayReadBilling = can(actor, "org:manage_billing", {
    kind: "billing",
    orgId: org.id,
  });

  const [issues, projects, billing] = await Promise.all([
    listIssues(actor, {
      orgId: org.id,
      assigneeId: actor.userId,
      status: ["todo", "in_progress", "in_review"],
      limit: RECENT_ISSUE_LIMIT,
    }),
    listProjects(actor, { orgId: org.id, limit: PROJECT_LIMIT }),
    mayReadBilling
      ? getBillingSummary(actor, org.id)
      : Promise.resolve<BillingSummary | null>(null),
  ]);

  return (
    <div className="space-y-12">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">{org.name}</h1>
        <p className="mt-1 text-sm text-slate-600">
          {projects.total} projects · {issues.total} issues assigned to you
        </p>
      </header>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Assigned to you
          </h2>
          <Link href={`/${orgSlug}/issues`} className="text-sm text-indigo-600">
            All issues
          </Link>
        </div>

        {issues.items.length === 0 ? (
          <EmptyState
            title="Nothing on your plate"
            description="Issues assigned to you show up here as soon as somebody picks you."
          />
        ) : (
          <ul className="space-y-2">
            {issues.items.map((issue) => (
              <li key={issue.id}>
                <IssueCard
                  issue={issue}
                  href={`/${orgSlug}/issues?issue=${issue.id}`}
                  compact
                />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Projects
          </h2>
          <Link href={`/${orgSlug}/projects`} className="text-sm text-indigo-600">
            All projects
          </Link>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {projects.items.map((row) => (
            <ProjectCard
              key={row.project.id}
              project={row.project}
              stats={row.stats}
              href={`/${orgSlug}/projects/${row.project.slug}`}
              actor={actor}
            />
          ))}
        </div>
      </section>

      {billing !== null ? (
        <section>
          <h2 className="mb-4 text-sm font-semibold uppercase tracking-wide text-slate-500">
            Usage
          </h2>
          <UsagePanel summary={billing} />
        </section>
      ) : null}
    </div>
  );
}
"use client";

/**
 * Header with search trigger, notifications and the user menu.
 *
 * Must call (do not reimplement): isEnabled
 */
import { Button } from "@/components/ui/button";
import { isEnabled } from "@/lib/feature-flags";
import { orgFlagContext } from "@/hooks/flag-context";
import { formatShortcut } from "@/hooks/shortcut-match";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor, User } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { ReactElement } from "react";
import { NotificationBell } from "../notification/notification-bell";
import { UserMenu } from "./user-menu";

export type TopBarProps = {
  org: Organization;
  actor: Actor;
  unreadCount: number;
  flags: FeatureFlagSnapshot;
  /** The signed-in user record, for the avatar menu. */
  user?: User;
  onOpenSearch?: () => void;
  onSignOut?: () => void;
};

export function TopBar(props: TopBarProps): ReactElement | null {
  const { org, actor, unreadCount, flags, user, onOpenSearch, onSignOut } =
    props;

  const context = orgFlagContext(org, actor);
  const paletteOn =
    flags.command_palette === true || isEnabled("command_palette", context);
  const advancedSearchOn =
    flags.advanced_search === true || isEnabled("advanced_search", context);

  return (
    <header className="top-bar flex items-center justify-between gap-3 border-b px-4 py-2">
      <span className="font-semibold">{org.name}</span>

      <div className="flex flex-1 justify-center">
        {paletteOn ? (
          <Button variant="secondary" size="sm" onClick={onOpenSearch}>
            {advancedSearchOn ? "Search issues, comments, projects" : "Search"}
            <span className="ml-2 text-xs text-neutral-500">
              {formatShortcut(["mod", "k"])}
            </span>
          </Button>
        ) : null}
      </div>

      <div className="flex items-center gap-2">
        <NotificationBell unreadCount={unreadCount} orgSlug={org.slug} />
        {user !== undefined ? (
          <UserMenu
            user={user}
            orgSlug={org.slug}
            onSignOut={onSignOut ?? (() => undefined)}
          />
        ) : null}
      </div>
    </header>
  );
}
